// @ts-check
// 생성됨: tools/sync-v2.js 가 design/ 에서 복사한 파일 — 직접 고치지 말 것(원본을 고친 뒤 다시 복사).
/* 판화풍 스킨 글꼴(@font-face, data URI). tools/build-fonts.cjs 가 만든 파일 — 직접 고치지 말 것.
 * skin.js 앞뒤 어느 쪽에 불러도 된다: Zap.skins.engraving.fontCss 에 들어간다. */
(function () {
  const g = /** @type {any} */ (globalThis);
  g.Zap = g.Zap || {};
  g.Zap.skins = g.Zap.skins || {};
  const css = "@font-face{font-family:\"EG Cinzel\";font-style:normal;font-weight:800;font-display:swap;src:url(data:font/woff2;base64,) format(\"woff2\");}\n@font-face{font-family:\"EG Fell SC\";font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format(\"woff2\");}\n@font-face{font-family:\"EG Garamond\";font-style:normal;font-weight:500;font-display:swap;src:url(data:font/woff2;base64,) format(\"woff2\");}\n@font-face{font-family:\"EG Garamond\";font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format(\"woff2\");}\n";
  g.Zap.skins._engravingFontCss = css;
  if (g.Zap.skins.engraving) g.Zap.skins.engraving.fontCss = css;
})();
